#define MENU_WIFI_DETECTOR_OUI_COUNT (sizeof(s_oui_table)/sizeof(s_oui_table[0]))

const char *menu_wifi_detector_oui_vendor(const uint8_t mac[6])
{
    if(mac == NULL)
    {
        return NULL;
    }
    if((mac[0] & 0x02U) != 0U)
    {
        return NULL; /* locally-administered (randomized/private) */
    }

    int lo = 0;
    int hi = (int)MENU_WIFI_DETECTOR_OUI_COUNT - 1;
    while(lo <= hi)
    {
        int mid = (lo + hi) / 2;
        int cmp = memcmp(s_oui_table[mid].oui, mac, 3);
        if(cmp == 0)
        {
            return s_oui_vendor_names[s_oui_table[mid].vendor];
        }
        if(cmp < 0)
        {
            lo = mid + 1;
        }
        else
        {
            hi = mid - 1;
        }
    }
    return NULL;
}

bool menu_wifi_detector_oui_is_random(const uint8_t mac[6])
{
    return (mac != NULL) && ((mac[0] & 0x02U) != 0U);
}
